try:
    from .celebi import QuantizeCelebi, ImageQuantizeCelebi
except (ImportError, ModuleNotFoundError):
    from PIL import Image

    def QuantizeCelebi(pixels, max_colors=128):
        counts = {}
        for p in pixels:
            rgb = ((p[0] & 0xFF) << 16) | ((p[1] & 0xFF) << 8) | (p[2] & 0xFF)
            counts[rgb] = counts.get(rgb, 0) + 1
        return counts

    def ImageQuantizeCelebi(image_path, quality=1, max_colors=128):
        try:
            with Image.open(image_path) as img:
                img = img.convert("RGB")
                img.thumbnail((128, 128))
                colors = img.getcolors(maxcolors=128 * 128)
                if colors:
                    res = {}
                    for count, rgb in colors:
                        val = ((rgb[0] & 0xFF) << 16) | ((rgb[1] & 0xFF) << 8) | (rgb[2] & 0xFF)
                        res[val] = count
                    return res
        except Exception:
            pass
        return {}